window.RI1_UNITS = {"12":{"unit":12,"code":"RI1-U12","title":"VANISHED","startNumber":297,"endNumber":312,"entries":[{"number":297,"term":"vanish (v) ~ disappear (v)","spoken":"vanish , disappear","ipa":"vanish /ˈvænɪʃ/ · disappear /ˌdɪsəˈpɪr/","type":"verb · word family","meaning":"biến mất","definition":"To disappear suddenly or completely from sight; disappear is the more general term.","note":"Các từ gần nghĩa trong nét nghĩa này nhưng có thể khác cấu trúc hoặc sắc thái; chú ý mẫu đi kèm.","example":"The climber vanished during the storm and appeared to disappear without leaving a clear trail."},{"number":298,"term":"summit (n)","spoken":"summit","ipa":"summit /ˈsʌmət/","type":"noun","meaning":"đỉnh núi","definition":"The highest point or top of a mountain.","note":"","example":"The team reached the summit shortly before the weather changed."},{"number":299,"term":"prove (v) · proof (n)","spoken":"prove , proof","ipa":"prove /pruːv/ · proof /pruːf/","type":"verb · noun · word family","meaning":"chứng minh · bằng chứng","definition":"To show that something is true; proof is the evidence that establishes it.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A footprint may prove that someone used the path, but stronger proof is still needed."},{"number":300,"term":"path (n)","spoken":"path","ipa":"path /pæθ/","type":"noun","meaning":"con đường, tuyến đường","definition":"A track or route used for walking or travelling from one place to another.","note":"","example":"Investigators followed a narrow path leading away from the camp."},{"number":301,"term":"likely (a,adv) · likelihood (n) >< unlikely (a)","spoken":"likely , likelihood , unlikely","ipa":"likely /ˈlaɪkli/ · likelihood /ˈlaɪkliˌhʊd/ · unlikely /əˈnlaɪkli/","type":"noun · adjective · adverb · word family","meaning":"có khả năng cao · khả năng/xác suất >< ít có khả năng","definition":"Likely means probable; likelihood is the chance that something will happen.","note":"be likely to + V; likelihood of + danh từ/V-ing; unlikely là trái nghĩa.","example":"The climber was likely to follow the main path, but the likelihood of a wrong turn remained high."},{"number":302,"term":"suffer (v) from st","spoken":"suffer from something","ipa":"suffer /ˈsʌfɚ/","type":"verb · phrase / pattern","meaning":"chịu đựng…","definition":"To experience pain, illness, or difficulty.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: suffer (v) from st","example":"Many students suffer from headaches when they do not sleep enough."},{"number":303,"term":"approach (v,n)","spoken":"approach","ipa":"approach /əˈproʊtʃ/","type":"verb · noun","meaning":"tiếp cận, đến gần · cách tiếp cận, phương pháp","definition":"To move closer to something; as a noun, a way of dealing with a task or problem.","note":"","example":"The rescue team approached the valley from the north and later changed its approach."},{"number":304,"term":"effort (n) ~ attempt (n,v)","spoken":"effort , attempt","ipa":"effort /ˈɛfɚt/ · attempt /əˈtɛmpt/","type":"verb · noun · word family","meaning":"công sức/sự nỗ lực ~ lần cố gắng/thử thực hiện","definition":"Effort is the physical or mental energy used to do something; an attempt is one act of trying, and attempt can also be a verb.","note":"effort chỉ công sức bỏ ra. attempt chỉ một lần cố làm; attempt vừa là danh từ vừa là động từ.","example":"The first attempt failed, but the research team made a greater effort during the second trial."},{"number":305,"term":"call for st","spoken":"call for something","ipa":"call /kɔːl/","type":"phrasal verb","meaning":"kêu gọi, đòi hỏi phải có…","definition":"To require something or publicly ask for it.","note":"call for + danh từ; trong văn cảnh này không phải “gọi điện cho”.","example":"The difficult search called for more equipment and a larger team."},{"number":306,"term":"head (v) for / to …","spoken":"head for or to …","ipa":"head /hɛd/","type":"verb","meaning":"đi về phía…","definition":"To travel or move in the direction of a particular place.","note":"","example":"At dawn, the missing climber headed for a lower valley."},{"number":307,"term":"inhabit (v) · uninhabited (a)","spoken":"inhabit , uninhabited","ipa":"inhabit /ˌɪˈnhæbət/ · uninhabited /ˌʌnɪˈnhæbətɪd/","type":"verb · adjective · word family","meaning":"sống/cư trú tại · không có người ở","definition":"To live in a place; uninhabited means that no people live there.","note":"inhabit + địa điểm, không có giới từ; uninhabited thường mô tả vùng đất hoặc đảo.","example":"Few people inhabit the region, and several valleys remain uninhabited."},{"number":308,"term":"detect (v)","spoken":"detect","ipa":"detect /dɪˈtɛkt/","type":"verb","meaning":"phát hiện ra…","definition":"To discover or notice something that is difficult to see or recognize.","note":"","example":"Thermal cameras can detect body heat in darkness."},{"number":309,"term":"decompose (v)","spoken":"decompose","ipa":"decompose /ˌdikəˈmpoʊz/","type":"verb","meaning":"phân hủy","definition":"To break down naturally into simpler substances, especially after death.","note":"","example":"Organic material decomposes more slowly in extremely cold conditions."},{"number":310,"term":"theory (n) >< practice (n) · theoretical (a)","spoken":"theory , practice , theoretical","ipa":"theory /ˈθɪri/ · practice /ˈpræktəs/ · theoretical /ˌθiɚˈɛtɪkəl/","type":"noun · adjective · word family","meaning":"lí thuyết >< việc áp dụng thực tế · thuộc lí thuyết","definition":"An explanation of ideas; actual use or action; based on ideas rather than action.","note":"theory nghĩa là hệ thống ý tưởng/lí thuyết; practice nghĩa là việc áp dụng thực tế; theoretical là tính từ.","example":"The theory sounds reasonable, but we need to test it in practice; the theoretical idea may work differently in real life."},{"number":311,"term":"investigate (v) · investigation (n) · investigator (n)","spoken":"investigate , investigation , investigator","ipa":"investigate /ˌɪˈnvɛstəˌɡeɪt/ · investigation /ˌɪˌnvɛstəˈɡeɪʃən/ · investigator /ˌɪˈnvɛstəˌɡeɪtɚ/","type":"verb · noun · word family","meaning":"điều tra/nghiên cứu · cuộc/sự điều tra · điều tra viên/người nghiên cứu","definition":"To examine facts carefully; a careful official examination.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The school investigated the missing books, and the investigation found them in another room."},{"number":312,"term":"approve (v) of st ~ agree (v) with st >< disapprove (v) of st","spoken":"approve of something , agree with something , disapprove of something","ipa":"approve /əˈpruːv/ · agree /əˈɡriː/ · disapprove /ˌdɪsəˈpruːv/","type":"verb · phrase / pattern · word family","meaning":"tán thành/cho là tốt ~ đồng ý/cùng ý kiến >< không tán thành","definition":"To agree with; to disagree with; agreement or disagreement.","note":"approve of nghĩa là cho là tốt/ủng hộ; agree with nghĩa là cùng ý kiến với; disapprove of nghĩa là không tán thành.","example":"Most parents approve of and agree with the change, while a few disapprove of it; the plan received more approval than disapproval."}],"pronunciationFocus":[{"entryNumber":304,"points":[{"category":"word-stress","note":"effort nhấn âm đầu; attempt nhấn trọng âm chính ở âm thứ hai"},{"category":"final-sound","note":"attempt /əˈtɛmpt/: giữ đủ cụm /mpt/ ở cuối"}]},{"entryNumber":307,"points":[{"category":"word-stress","note":"inhabit và uninhabited đều giữ trọng âm chính ở /ˈnhæb/"}]},{"entryNumber":308,"points":[{"category":"final-sound","note":"detect /dɪˈtɛkt/: giữ đủ cụm /kt/ ở cuối"}]},{"entryNumber":310,"points":[{"category":"word-stress","note":"theory nhấn âm đầu; theoretical chuyển trọng âm chính sang /ˈɛ/"}]},{"entryNumber":311,"points":[{"category":"word-stress","note":"investigate nhấn /ˈnvɛs/; investigation chuyển trọng âm chính sang /ˈɡeɪ/"}]},{"entryNumber":312,"points":[{"category":"linking","note":"approve‿of và disapprove‿of: nối /v/ cuối động từ với nguyên âm đầu của of"}]}]}};
